(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[169],{1508:function(t,n,e){"use strict";e.r(n),n.default={code:"M1-02",title:"清單資料分析挑戰",tier:"t1",unlockCode:"M1-02-ListAnalysis",tasks:[{id:"count-017",code:"M1-02-count-017",title:"倒轉時光",description:"勇者獲得了一個「時光倒流」的魔法卷軸。這個卷軸上有一串數字密碼，但是必須從最後一個數字讀回到第一個數字，魔法才能生效。 請讀取一個清單，並將清單內的數字「由後往前」印出來。\n輸入格式\n輸入共有兩行。第一行是一個整數 N，代表密碼長度。\n第二行輸入 N 個整數，代表N個數字的密碼組合。\n程式反序輸 N 筆密碼數字資料，中間以空白間隔\n(提示：循環計數迴圈起點設為清單長度，終點設為 1，間隔設為 -1)",examples:[{input:"4\n10 20 30 40",output:"40 30 20 10",explanation:"第一行輸入數字4，代表密碼有4筆資料\n第二行有4筆整數資料，10 20 30 40\n程式反敘輸出密碼資料：40 30 20 10"},{input:"3\n1 2 3",output:"3 2 1",explanation:"第一行輸入數字3，代表密碼有3筆資料\n第二行有3筆整數資料，1 2 3\n程式反敘輸出密碼資料：3 2 1"}],testCases:[{input:"2\n100 20",expectedOutput:"20 100",score:10},{input:"4\n7 7 9 7",expectedOutput:"7 9 7 7",score:10},{input:"5\n1 2 3 4 5",expectedOutput:"5 4 3 2 1",score:10},{input:"4\n0 1 0 1",expectedOutput:"1 0 1 0",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-02-ListAnalysis/count-017.sb3"},{id:"count-018",code:"M1-02-count-018",title:"冒險日誌",description:"勇者寫了 N 天的冒險日誌，清單中依序記錄了每天打倒的怪物數量。\n例如清單的第一個數字是第 1 天打倒的數量，第二個數字是第 2 天的...\n請你格式化輸出每天的戰績，格式為：Day-[第幾天]-[數量]。\n輸入格式\n輸入共有兩行。第一行是一個整數 N，代表天數。\n第二行輸入 N 個整數，代表每天怪物的數量。\n程式依序輸出 N 天資料，每天格式為 Day-i-數量 不同天中間以空白間隔。",examples:[{input:"2\n15 5",output:"Day-1-15 Day-2-5",explanation:"第一行輸入數字2，代表有2天資料\n第二行有2筆整數資料，15 5\n程式依序輸出所有天數資料：Day-1-15 Day-2-5"},{input:"3\n12 15 20",output:"Day-1-12 Day-2-15 Day-3-20",explanation:"第一行輸入數字3，代表有3天資料\n第二行有3筆整數資料，12 15 20\n程式依序輸出所有天數資料：Day-1-12 Day-2-15 Day-3-20"}],testCases:[{input:"1\n100",expectedOutput:"Day-1-100",score:10},{input:"4\n7 7 9 7",expectedOutput:"Day-1-7 Day-2-7 Day-3-9 Day-4-7",score:10},{input:"4\n33 22 44 11",expectedOutput:"Day-1-33 Day-2-22 Day-3-44 Day-4-11",score:10},{input:"3\n25 2 3",expectedOutput:"Day-1-25 Day-2-2 Day-3-3",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M1-02-ListAnalysis/count-018.sb3"},{id:"count-016",code:"M1-02-count-016",title:"合格的裝備",description:"勇者的負重能力有限，他只能攜帶重量「小於 10」的輕型裝備。 現在清單中有一堆裝備的重量，請你利用迴圈檢查每一個裝備，只把重量小於 10 的裝備重量印出來。\n輸入格式\n輸入共有兩行。第一行是一個整數 N，代表裝備數量。\n第二行輸入 N 個整數，代表每個裝備重量。\n程式依序輸出小於 10 的數字，中間以空白隔開。\n如果都沒有小於 10 的數字，則什麼都不輸出。",examples:[{input:"5\n15 5 20 8 3",output:"5 8 3",explanation:"第一行輸入數字5，代表5筆裝備資料\n第二行有5筆整數裝備資料，15 5 20 8 3\n程式依序輸出小於10裝備重量：5 8 3"},{input:"3\n12 15 20",output:"",explanation:"第一行輸入數字3，代表3筆裝備資料\n第二行有3筆整數裝備資料，12 15 20\n沒有小於10裝備輸出為空："}],testCases:[{input:"3\n1 2 3",expectedOutput:"1 2 3",score:10},{input:"6\n7 15 7 24 9 7",expectedOutput:"7 7 9 7",score:10},{input:"4\n33 5 44 11",expectedOutput:"5",score:10},{input:"5\n3 8 11 69 77",expectedOutput:"3 8",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-02-ListAnalysis/count-016.sb3"},{id:"TYTN-05",code:"M1-02-TYTN-05",title:"班服投票",description:"可愛國小601班要製作紀念班服，本次班服設計共有3個款式，分別編號為1、2、3。\n每位同學可在選票上寫下自己選擇的班服款式編號，最後以得票數最高者為班服樣式。\n請先計算每款班服的得票數（依1→3順序），並輸出最高票的班服編號。\n若有兩款或以上的票數相同且為最高票，則輸出：請重新投票",examples:[{input:"8\n1 2 2 3 2 1 3 2",output:"2",explanation:"8 位同學投票，各自選擇的班服編號如上。\n2 號班服得票最高，因此輸出 2。"},{input:"6\n1 2 3 1 2 3",output:"請重新投票",explanation:"3 種班服皆獲得 2 票，最高票有同票情形。\n因此輸出「請重新投票」。"}],testCases:[{input:"8\n1 2 2 3 2 1 3 2",expectedOutput:"2",score:10},{input:"6\n1 2 3 1 2 3",expectedOutput:"請重新投票",score:10},{input:"5\n1 1 1 2 3",expectedOutput:"1",score:10},{input:"7\n3 3 2 2 1 3 2",expectedOutput:"請重新投票",score:10},{input:"4\n2 2 2 3",expectedOutput:"2",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-02-ListAnalysis/TYTN-05.sb3"},{id:"TYTN-06",code:"M1-02-TYTN-06",title:"棒球場座位",description:"小明想去看棒球賽為台灣隊加油，請寫一個程式，輸入觀眾的座位號碼後，能輸出該座位所屬的大區、所在排數與該排中的第幾個座位，讓小明能迅速找到座位。\n棒球場共有 9000 個座位，分為三大區：\n第1區（普通區）：2250 席，每排 25 人，共 90 排。\n第2區（搖滾區）：4500 席，每排 50 人，共 90 排。\n第3區（普通區）：2250 席，每排 25 人，共 90 排。\n座位編號從第1區開始，由左至右、由前至後依序編號，接著接續第2、3區",examples:[{input:"1881",output:"1 76 6",explanation:"座位 1881 位於第1區。\n第1區每排25人，因此計算後位於第76排、第6個座位。"},{input:"3045",output:"2 16 45",explanation:"座位 3045 位於第2區。\n第2區每排50人，因此計算後位於第16排、第45個座位。"}],testCases:[{input:"1881",expectedOutput:"1 76 6",score:10},{input:"3045",expectedOutput:"2 16 45",score:10},{input:"25",expectedOutput:"1 1 25",score:10},{input:"4501",expectedOutput:"2 46 1",score:10},{input:"8999",expectedOutput:"3 90 24",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-02-ListAnalysis/TYTN-06.sb3"},{id:"W3-05",code:"M1-02-W3-05",title:"風獅爺排隊",description:"金門各村落的風獅爺要準備祭典大合照，村長要求將 4 尊風獅爺依照身高「由矮到高」排好。\n工讀生小金負責進行搬動，規則如下：\n【比較規則】\n每次只比較「相鄰」的兩尊風獅爺（第 1 與第 2、 第 2 與第 3、 第 3 與第 4）。\n【交換規則】\n如果左邊的風獅爺身高 > 右邊的風獅爺身高，兩尊就必須交換位置。\n【紀錄規則】\n每成功交換一次位置，小金就記錄 1 次（統計總交換次數）。\n【任務】\n(1) 將輸入的 4 個身高數值由小到大排列。\n(2) 在依照上述「相鄰比較、需要就交換」的排序過程中，計算總共交換了幾次。\n【排序流程說明】\n請使用以下固定流程（類似氣泡排序 Bubble Sort）：\n重複進行 3 回合：\n第 1 回合依序比較 (1,2)、(2,3)、(3,4)\n第 2 回合依序比較 (1,2)、(2,3)、(3,4)\n第 3 回合依序比較 (1,2)、(2,3)、(3,4)\n每次比較時只要符合交換規則就交換，並將交換次數 +1。",examples:[{input:"4\n150 120 110 100",output:"100 110 120 150 6",explanation:"這是「最麻煩」的情況（全倒過來排）。\n150 要一路換到最後，接著 120 再換，總共會交換 6 次。"},{input:"4\n120 110 140 130",output:"110 120 130 140 2",explanation:"120 與 110 換一次；140 與 130 換一次，總共 2 次。"}],testCases:[{input:"4\n100 110 120 130",expectedOutput:"100 110 120 130 0",score:10},{input:"4\n150 120 110 100",expectedOutput:"100 110 120 150 6",score:15},{input:"4\n120 110 140 130",expectedOutput:"110 120 130 140 2",score:20},{input:"4\n130 120 120 110",expectedOutput:"110 120 120 130 5",score:25},{input:"4\n115 130 105 120",expectedOutput:"105 115 120 130 3",score:30}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-02-ListAnalysis/W3-05.sb3"},{id:"W5-01",code:"M1-02-W5-01",title:"安靜值巡查器",description:"學校自習室裝了「安靜值巡查器」，每小時會量測一次安靜值（數值越大代表越安靜）。系統設定一個門檻值 K：\n- 若某小時的安靜值",examples:[{input:"5\n100\n120 80 70 100 60",output:"4",explanation:"第2小時(80<100)：+1\n第3小時(70<100)：連續第2小時 +2\n第4小時(100≥100)：中斷\n第5小時(60<100)：+1\n總計 4"},{input:"4\n10\n0 0 0 0",output:"7",explanation:"連續4小時都未達標：+1 +2 +2 +2 = 7"}],testCases:[{input:"5\n100\n120 130 140 150 160",expectedOutput:"0",score:10},{input:"4\n10\n0 0 0 0",expectedOutput:"7",score:10},{input:"6\n50\n40 60 40 40 60 40",expectedOutput:"5",score:10},{input:"7\n100\n90 90 90 100 90 90 110",expectedOutput:"8",score:10},{input:"1\n1\n0",expectedOutput:"1",score:10},{input:"8\n1000\n999 1000 999 999 999 1000 999 1000",expectedOutput:"7",score:10},{input:"10\n5\n5 4 3 2 1 0 5 4 5 4",expectedOutput:"11",score:10},{input:"9\n100\n99 99 100 99 100 99 99 99 100",expectedOutput:"9",score:10},{input:"12\n7\n7 6 7 6 6 6 7 6 7 6 6 7",expectedOutput:"10",score:10},{input:"15\n50\n10 60 10 60 10 60 10 60 10 60 10 60 10 60 10",expectedOutput:"8",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-02-ListAnalysis/W5-01.sb3"},{id:"WP-03",code:"M1-02-WP-03",title:"電影院找座位",description:"小華一家人要去看電影，他們希望能找到連續的K個空座位。整排座位中，某些座位已經有人坐了，因此剩下的空位會形成幾段「連續空位」。\n現在給你每一段連續空位的座位數，請你計算小華一家人共有幾種方式 可以在這一排中坐下。\n\n第一行：整數 N，代表有N個人。\n\n第二行：輸入 M，代表有M個空段落。\n\n第三行：輸入序列X，依序代表每個空段落的座位數。",examples:[{input:"3\n2\n6 2",output:"4",explanation:"有3個人\n有2段空位：6 與 2。\n長度 6 的那段，能讓 3 人連坐的起點有 4 種。\n長度 2 的那段不夠 3 人連坐，0 種。\n合計 4 種。"},{input:"2\n3\n3 5 4",output:"9",explanation:"有2個人\n有3段空位：3、5、4。\n長度 3 的那段：可放 2 人的起點有 2 種。\n長度 5 的那段：有 4 種。\n長度 4 的那段：有 3 種。\n合計 2 + 4 + 3 = 9 種。"}],testCases:[{input:"3\n2\n6 2",expectedOutput:"4",score:10},{input:"2\n3\n3 5 4",expectedOutput:"9",score:10},{input:"4\n1\n4",expectedOutput:"1",score:10},{input:"5\n3\n1 3 4",expectedOutput:"0",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-02-ListAnalysis/WP-03.sb3"},{id:"cycjunior-004",code:"M1-02-cycjunior-004",title:"校車廣播系統熱血指數統計",description:"快樂國中一年級的戶外教學日終於到了！全班同學興高采烈地搭上了前往遊樂園的校車。然而，去程的高速公路意外地塞車了，原本歡樂的氣氛隨著車窗外的景色靜止，車內的空氣也開始變得沉悶，同學們一個個開始打哈欠，甚至有人睡著了。\n身為康樂股長的小明，手中掌握著一份班上同學投票選出的「熱門歌曲清單」。這份清單上的每一首歌，根據節奏快慢與受歡迎程度，都有一個對應的「熱血指數」。指數越高，代表這首歌越能讓大家High起來（當然，如果是抒情歌，指數可能就很低，甚至如果是老師愛聽的老歌，指數可能是負的，會讓大家更想睡覺）。\n校車的廣播系統有一個特殊的限制：一次設定只能連續播放 K 首歌曲。一旦開始播放，就必須把這 K 首歌依序播完才能切換模式。小明的任務非常重要，他需要從這份落落長的歌單中，挑選出連續的 K 首歌，使得這段時間內的「熱血指數總和」達到最高，以此來喚醒全班同學的靈魂，把車內的氣氛炒到最高點！\n請你寫一個程式幫助小明，在給定的歌單順序中，找出那一段連續 K 首歌的熱血總和最大是多少",examples:[{input:"3\n5\n10 20 30 10 50",output:"90",explanation:"(10+20+30)=60\n(20+30+10)=60\n(30+10+50)=90 (最大)"},{input:"2\n4\n5 100 100 5",output:"200",explanation:"連續2首的組合：\n(5+100)=105, (100+100)=200, (100+5)=105。\n最大值為 200。"}],testCases:[{input:"2\n4\n1 2 3 4",expectedOutput:"7",score:10},{input:"3\n5\n5 5 5 5 5",expectedOutput:"15",score:15},{input:"2\n5\n100 10 10 10 100",expectedOutput:"110",score:20},{input:"4\n8\n1 2 100 100 100 2 1 1",expectedOutput:"302",score:25},{input:"3\n6\n50 10 50 10 50 10",expectedOutput:"110",score:30}],difficulty:"L4",difficultyLabel:"L4｜精熟",sb3Path:"m0/M1-02-ListAnalysis/cycjunior-004.sb3"}]}}}]);